package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_write_TriageGen1Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;
    private static final int BLOCK_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        // Using default block size 512
        tarOut = new TarArchiveOutputStream(out, BLOCK_SIZE);
    }







    @Test
    public void testWrite_FullCoverage_AssemblyAndLargeWrite() throws IOException {
        // To trigger all branches, we need a scenario where:
        // 1. assemLen > 0
        // 2. (assemLen + numToWrite) >= recordBuf.length  (The first if block in assemLen > 0)
        // 3. numToWrite > 0 and numToWrite < recordBuf.length (The while loop)
        // 4. numToWrite >= recordBuf.length (The while loop direct write)

        // Since we cannot easily mock the internal recordBuf length or assemLen via public API,
        // we use the blockSize to control the behavior.

        int blockSize = 10; // Small block size to trigger assembly logic easily
        tarOut = new TarArchiveOutputStream(out, blockSize);

        int totalSize = 50;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(totalSize);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[totalSize];
        for (int i = 0; i < totalSize; i++) data[i] = (byte) i;

        // 1. Write small part to set assemLen > 0
        tarOut.write(data, 0, 4); 

        // 2. Write part that makes (assemLen + numToWrite) >= recordBuf.length
        // assemLen is 4. recordBuf.length is 10. Need 6 more.
        tarOut.write(data, 4, 6); 

        // 3. Write part that goes into the while loop directly (numToWrite >= recordBuf.length)
        // Current assemLen is 0. 
        // Let's write exactly 10.
        tarOut.write(data, 10, 10);

        // 4. Write part that goes into the while loop (numToWrite < recordBuf.length)
        tarOut.write(data, 20, 5);

        tarOut.closeArchiveEntry();
        tarOut.finish();

        // Verify that we didn't crash and processed bytes
        Assert.assertTrue(out.size() > 0);
    }




}

