        tarOut.write(data, 0, 30);

        tarOut.closeArchiveEntry();
        tarOut.finish();

        // The records are written directly. 
        // Note: TarArchiveOutputStream implementation details for writeRecord might vary,
        // but we are testing the logic paths of the provided 'write' method.
        Assert.assertTrue(out.size() >= 30);
    }


}

